<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount} from 'vue'
import type {Dashboard} from '../api/types'
import type {EChartsOption} from 'echarts'
import {useResource,money,number,dateTime} from '../composables/useResource'
import {useMediaQuery} from '../composables/useMediaQuery'
import {useAuth} from '../stores/auth'
import PageHeader from '../components/PageHeader.vue'
import ResourceState from '../components/ResourceState.vue'
import ChartPanel from '../components/ChartPanel.vue'
import StatusTag from '../components/StatusTag.vue'
import RoleWorkbench from '../components/RoleWorkbench.vue'
const actionLabels:Record<string,string>={LOGIN:'用户登录',LOGOUT:'用户退出',CREATE:'新建档案',UPDATE:'更新档案',DELETE:'删除档案',PROGRESS:'更新项目进度',SAVE_REQUEST:'保存采购申请',SUBMIT_REQUEST:'提交采购审批',APPROVED:'采购审批通过',REJECTED:'采购审批驳回',RECORD_QUOTE:'录入供应商报价',AWARD_ORDER:'中选并生成订单',CANCEL_ORDER:'取消采购订单',CLOSE_ORDER:'关闭剩余采购',REORDER_REQUEST:'生成补采申请',RETURN_ISSUE:'项目退料入库',RETURN_PURCHASE:'办理采购退货',REGISTER_SUPPLIER_REFUND:'收到供应商退款',RECEIVE_STOCK:'验收入库',ISSUE_STOCK:'项目领料出库',RECORD_COST:'登记成本费用',SAVE_CONTRACT:'保存合同',DELETE_CONTRACT:'删除合同',UPLOAD_CONTRACT:'上传合同附件',REGISTER_PAYMENT:'登记付款',APPLY_PAYMENT:'提交付款申请',PAYMENT_SUBMITTED:'提交付款申请',PAYMENT_APPROVED:'付款申请通过',PAYMENT_REJECTED:'付款申请驳回',PAYMENT_CANCELLED:'撤回付款申请',PAYMENT_PAID:'执行付款申请',DEMO_SEED:'初始化演示数据'}
function actionLabel(action?:string){return action?actionLabels[action]||action:'业务更新'}
const auth=useAuth(),isMobile=useMediaQuery()
const {data,loading,error,load}=useResource<Dashboard>('/dashboard',{metrics:{},budget_vs_cost:[],monthly_purchases:[],cost_composition:[],project_progress:[],order_status:[],todos:[],recent_activity:[]})
const cards=[{key:'active_projects',label:'在建项目',unit:'个',icon:'▦',desc:'当前进行中的工程',amount:false},{key:'contract_amount',label:'合同总额',unit:'元',icon:'▤',desc:'项目合同金额',amount:true},{key:'completed_value',label:'已完成产值',unit:'元',icon:'↗',desc:'按服务端进度统计',amount:true},{key:'budget_amount',label:'项目总预算',unit:'元',icon:'◎',desc:'已建立项目的预算',amount:true},{key:'actual_cost',label:'实际成本',unit:'元',icon:'◷',desc:'领料及各项费用',amount:true},{key:'purchase_amount',label:'净采购订单额',unit:'元',icon:'▧',desc:'采购执行规模',amount:true},{key:'pending_requests',label:'待审批申请',unit:'笔',icon:'◈',desc:'需要关注的审批事项',amount:false},{key:'outstanding_amount',label:'应付未付',unit:'元',icon:'￥',desc:'实际验收入库应付款',amount:true}]
const visibleCards=computed(()=>cards.filter(c=>data.value.metrics[c.key]!==undefined&&(!data.value.workbench||data.value.workbench.metric_keys.includes(c.key))))
const chartAllowed=(key:string)=>!data.value.workbench||data.value.workbench.chart_keys.includes(key)
const roleNames:Record<string,string>={admin:'系统管理',boss:'企业负责人',manager:'项目经理',buyer:'采购专员',warehouse:'仓库管理',finance:'财务管理'}
let timer:ReturnType<typeof setInterval>|undefined,refreshTimer:ReturnType<typeof setTimeout>|undefined
const refreshWorkspace=()=>{if(document.visibilityState==='visible'){clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>load(),180)}}
onMounted(()=>{window.addEventListener('zqy:changed',refreshWorkspace);window.addEventListener('focus',refreshWorkspace);document.addEventListener('visibilitychange',refreshWorkspace);timer=setInterval(refreshWorkspace,30000)})
onBeforeUnmount(()=>{window.removeEventListener('zqy:changed',refreshWorkspace);window.removeEventListener('focus',refreshWorkspace);document.removeEventListener('visibilitychange',refreshWorkspace);clearInterval(timer);clearTimeout(refreshTimer)})
const palette=['#356aeb','#79a2fa','#38b6a1','#f2b65c','#a4b1cc']
const axis={axisLine:{show:false},axisTick:{show:false},axisLabel:{color:'#8390a5',fontSize:11},splitLine:{lineStyle:{color:'#edf0f5',type:'dashed' as const}}}
const budgetOption=computed<EChartsOption>(()=>({
  color:palette,tooltip:{trigger:'axis',valueFormatter:(v)=>money(v)+' 元'},legend:{bottom:0,itemWidth:10,itemHeight:10,textStyle:{color:'#7b879a'}},
  grid:isMobile.value?{left:100,right:16,top:15,bottom:50}:{left:72,right:20,top:15,bottom:65},
  xAxis:isMobile.value?{type:'value',...axis,splitNumber:3,axisLabel:{...axis.axisLabel,formatter:(v:number)=>Math.abs(v)>=10000?number(v/10000,0)+'万':number(v,0)}}:{type:'category',data:data.value.budget_vs_cost.map(r=>r.name),...axis,axisLabel:{color:'#7b879a',width:90,overflow:'truncate',interval:0}},
  yAxis:isMobile.value?{type:'category',data:data.value.budget_vs_cost.map(r=>r.name),...axis,axisLabel:{...axis.axisLabel,width:82,overflow:'truncate'}}:{type:'value',...axis,axisLabel:{formatter:(v:number)=>number(v,0)}},
  series:[{name:'项目预算',type:'bar',barMaxWidth:22,data:data.value.budget_vs_cost.map(r=>Number(r.budget)),itemStyle:{borderRadius:isMobile.value?[0,4,4,0]:[4,4,0,0]}},{name:'实际成本',type:'bar',barMaxWidth:22,data:data.value.budget_vs_cost.map(r=>Number(r.cost)),itemStyle:{borderRadius:isMobile.value?[0,4,4,0]:[4,4,0,0],color:'#38b6a1'}}]
}))
const purchaseOption=computed<EChartsOption>(()=>({color:palette,tooltip:{trigger:'axis',valueFormatter:v=>money(v)+' 元'},grid:{left:70,right:20,top:15,bottom:32},xAxis:{type:'category',data:data.value.monthly_purchases.map(r=>r.month),...axis,boundaryGap:false},yAxis:{type:'value',...axis},series:[{name:'月度采购金额',type:'line',smooth:true,symbolSize:7,lineStyle:{width:3},areaStyle:{color:'#eaf0ff'},data:data.value.monthly_purchases.map(r=>Number(r.amount))}]}))
const composition=computed<EChartsOption>(()=>data.value.cost_composition.some(r=>Number(r.value)<0)?({color:palette,tooltip:{trigger:'axis',valueFormatter:(v)=>money(v)+' 元'},grid:{left:90,right:20,top:20,bottom:40},xAxis:{type:'value',...axis,axisLabel:{...axis.axisLabel,formatter:(v:number)=>Math.abs(v)>=10000?number(v/10000,0)+'万':number(v,0)}},yAxis:{type:'category',data:data.value.cost_composition.map(r=>r.name),...axis},series:[{type:'bar',data:data.value.cost_composition.map(r=>Number(r.value)),colorBy:'data'}]}):({color:palette,tooltip:{trigger:'item',formatter:'{b}: {c} 元 ({d}%)'},legend:{bottom:0,itemWidth:9,itemHeight:9},series:[{type:'pie',radius:['48%','70%'],center:['50%','43%'],label:{show:false},data:data.value.cost_composition.map(r=>({name:r.name,value:Number(r.value)})),itemStyle:{borderColor:'#fff',borderWidth:4,borderRadius:5}}]}))
const statusOption=computed<EChartsOption>(()=>({color:palette,tooltip:{trigger:'item'},legend:{bottom:0,itemWidth:9,itemHeight:9},series:[{type:'pie',radius:['48%','70%'],center:['50%','43%'],label:{show:false},data:data.value.order_status.map(r=>({name:({OPEN:'待收货',PARTIAL:'部分收货',COMPLETED:'已完成',CANCELLED:'已取消',CLOSED:'已关闭'} as Record<string,string>)[r.name]||r.name,value:Number(r.value)})),itemStyle:{borderColor:'#fff',borderWidth:4,borderRadius:5}}]}))
</script>
<template><PageHeader :title="`${roleNames[auth.user?.role||'']||'企业'}工作台`" subtitle="从真实业务状态生成待办，处理后刷新；只展示当前授权数据。"><span class="date-pill">{{new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'})}}</span><el-button :loading="loading" @click="load">刷新数据</el-button></PageHeader><ResourceState :loading="loading" :error="error" @retry="load"><RoleWorkbench v-if="data.workbench" :model="data.workbench"/><el-alert v-if="Number(data.metrics.refund_due_amount)>0" :title="`供应商待收退款 ¥ ${money(data.metrics.refund_due_amount)}`" description="采购退货已形成退款余额，请在应付与付款中核对实际到账。" type="warning" show-icon :closable="false" class="mb"/><div class="metrics-grid"><article v-for="(card,i) in visibleCards" :key="card.key" class="metric-card"><div class="metric-top"><span>{{card.label}}</span><b class="metric-icon" :class="`tone-${i%4}`">{{card.icon}}</b></div><div class="metric-value"><span>{{card.amount?money(data.metrics[card.key]):number(data.metrics[card.key],0)}}</span><small>{{card.unit}}</small></div><p>{{card.desc}}</p></article></div><div class="charts-grid"><ChartPanel v-if="auth.can('cost:read')&&chartAllowed('budget')" title="项目预算与实际成本" subtitle="预算执行情况 · 元" :option="budgetOption" :empty="!data.budget_vs_cost.length"/><ChartPanel v-if="auth.can('order:read')&&chartAllowed('purchases')" title="月度采购趋势" subtitle="采购订单金额 · 元" :option="purchaseOption" :empty="!data.monthly_purchases.length"/></div><div class="charts-three"><ChartPanel v-if="auth.can('cost:read')&&chartAllowed('composition')" title="成本构成" subtitle="项目实际发生费用" :option="composition" :empty="!data.cost_composition.length" :height="250"/><ChartPanel v-if="auth.can('order:read')&&chartAllowed('order_status')" title="采购执行状态" subtitle="订单履约分布" :option="statusOption" :empty="!data.order_status.length" :height="250"/><section v-if="['boss','admin','manager'].includes(auth.user?.role||'')" class="panel"><div class="panel-heading"><h2>项目进度</h2><span class="muted">工程履约</span></div><el-empty v-if="!data.project_progress.length" description="暂无项目进度" :image-size="65"/><div class="progress-item" v-for="project in data.project_progress" :key="project.name"><div><span>{{project.name}}</span><b>{{number(project.progress,1)}}%</b></div><el-progress :percentage="Math.max(0,Math.min(100,Number(project.progress)))" :show-text="false" :stroke-width="7"/></div></section></div><div class="charts-grid"><section v-if="!data.workbench" class="panel"><div class="panel-heading"><h2>待办事项</h2><el-button v-if="auth.can('request:approve')&&auth.hasMenu('approvals')" link type="primary" @click="$router.push('/approvals')">前往审批中心 →</el-button></div><el-empty v-if="!data.todos.length" description="暂无待办事项" :image-size="60"/><div v-for="(todo,i) in data.todos" :key="todo.id||i" class="activity-row"><span class="activity-dot"/><div><b>{{todo.title||todo.code||todo.name}}</b><p>{{todo.description||todo.project_name||todo.note||'采购审批待处理'}}</p></div><StatusTag :value="todo.status||'PENDING'"/></div></section><section v-if="auth.can('system:manage')" class="panel"><div class="panel-heading"><h2>最近业务动态</h2><span class="muted">服务端业务记录</span></div><el-empty v-if="!data.recent_activity.length" description="暂无业务动态" :image-size="60"/><div v-for="(activity,i) in data.recent_activity" :key="activity.id||i" class="activity-row"><span class="activity-dot green"/><div><b>{{activity.title||(activity.action?actionLabel(activity.action):activity.code)}}</b><p>{{activity.description||activity.detail||activity.operator_name}}</p></div><time>{{dateTime(activity.created_at)}}</time></div></section></div></ResourceState></template>
